script:
(function () {
  'use strict';
  // Five-key TVM solver (N, I/Y, PV, PMT, FV with P/Y, C/Y and END/BGN), as on a financial
  // calculator. With i = rate per payment period and due = 1 in BGN mode:
  //   PV(1 + i)^N + PMT(1 + i x due)[((1 + i)^N - 1) / i] + FV = 0
  // (cash out negative, cash in positive). i = (1 + I/Y / C/Y)^(C/Y / P/Y) - 1, and a solved i is
  // converted back to I/Y = C/Y x ((1 + i)^(P/Y / C/Y) - 1). FV, PV and PMT are closed form, N uses
  //   (1 + i)^N = (PMT' - FV i) / (PMT' + PV i), PMT' = PMT(1 + i x due),
  // and I/Y is found by scanning for a sign change and bisecting (root nearest 0%).
  // Checked in Node (five.test.js): N 360, I/Y 6, PV 300,000, FV 0, P/Y = C/Y = 12 -> PMT -1,798.65
  // (standard mortgage table); computing back from the rounded -1,798.65 gives N 360.0009, I/Y 6% and PV 300,000.01;
  // N 10, I/Y 5, PMT -1,000, P/Y = C/Y = 1, END -> FV 12,577.89, BGN -> 13,206.79 (annuity tables);
  // N 5, PV -1,000, FV 1,500, P/Y = C/Y = 1 -> I/Y 8.4472% (1.5^(1/5) - 1); P/Y 12, C/Y 2 at 6% ->
  // 0.493862% a month (Canadian-mortgage style conversion 1.03^(1/6) - 1); I/Y 0 -> plain sums.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var KEYS = ['n', 'iy', 'pv', 'pmt', 'fv'];
  var RADIOS = { n: 'tvSolveN', iy: 'tvSolveIy', pv: 'tvSolvePv', pmt: 'tvSolvePmt', fv: 'tvSolveFv' };
  var INPUTS = { n: 'tvN', iy: 'tvIy', pv: 'tvPv', pmt: 'tvPmt', fv: 'tvFv' };
  var NAMES = { n: 'N', iy: 'I/Y', pv: 'PV', pmt: 'PMT', fv: 'FV' };
  var OUTPUTS = ['tvAnswer', 'tvTotalPmt', 'tvTotalInt', 'tvNOut', 'tvIyOut', 'tvPvOut', 'tvPmtOut', 'tvFvOut', 'tvPeriodRate', 'tvEar', 'tvYears'];
  var MAX_ROWS = 600;

  // --- calc start
  function annuity(i, n, due) {
    var f = Math.abs(i) < 1e-12 ? n : (Math.pow(1 + i, n) - 1) / i;
    return due ? f * (1 + i) : f;
  }
  function tvm(n, i, pv, pmt, fv, due) { return pv * Math.pow(1 + i, n) + pmt * annuity(i, n, due) + fv; }
  function solveFv(n, i, pv, pmt, due) { return -(pv * Math.pow(1 + i, n) + pmt * annuity(i, n, due)); }
  function solvePv(n, i, pmt, fv, due) { return -(fv + pmt * annuity(i, n, due)) / Math.pow(1 + i, n); }
  function solvePmt(n, i, pv, fv, due) {
    var a = annuity(i, n, due);
    return a === 0 ? NaN : -(pv * Math.pow(1 + i, n) + fv) / a;
  }
  function solveN(i, pv, pmt, fv, due) {
    if (Math.abs(i) < 1e-12) return pmt === 0 ? NaN : -(pv + fv) / pmt;
    var p = pmt * (due ? 1 + i : 1), top = p - fv * i, bottom = p + pv * i;
    if (bottom === 0 || top / bottom <= 0) return NaN;
    return Math.log(top / bottom) / Math.log(1 + i);
  }
  function solveRate(n, pv, pmt, fv, due) {
    var grid = [-0.99], k, best = NaN;
    for (k = -0.99; k < -1e-6; k = k * 0.9) grid.push(k);
    for (k = -1e-6; k < 10; k = k < 0 ? 1e-6 : k * 1.1) grid.push(k);
    grid.push(10);
    for (var g = 1; g < grid.length; g++) {
      var a = grid[g - 1], b = grid[g], fa = tvm(n, a, pv, pmt, fv, due), fb = tvm(n, b, pv, pmt, fv, due);
      if (!isFinite(fa) || !isFinite(fb)) continue;
      var root = NaN;
      if (fa === 0) root = a;
      else if (fa * fb < 0) {
        for (var it = 0; it < 200; it++) {
          var mid = (a + b) / 2, fm = tvm(n, mid, pv, pmt, fv, due);
          if (fm === 0) { a = b = mid; break; }
          if (fa * fm < 0) b = mid; else { a = mid; fa = fm; }
        }
        root = (a + b) / 2;
      }
      if (!isNaN(root) && (isNaN(best) || Math.abs(root) < Math.abs(best))) best = root;
    }
    return best;
  }
  function periodRate(iy, cy, py) { return Math.pow(1 + iy / cy, cy / py) - 1; }
  function annualRate(i, cy, py) { return cy * (Math.pow(1 + i, py / cy) - 1); }
  // Balance after each whole period (sign of PV); rows of `group` periods.
  function schedule(n, i, pv, pmt, due, group) {
    var bal = pv, rows = [], gP = 0, gI = 0, whole = Math.floor(n + 1e-9);
    for (var k = 1; k <= whole; k++) {
      var g;
      if (due) { bal += pmt; g = bal * i; bal += g; } else { g = bal * i; bal += g + pmt; }
      gP += pmt; gI += g;
      if (k % group === 0 || k === whole) { rows.push({ label: Math.ceil(k / group), part: k % group !== 0, pmt: gP, int: gI, bal: bal }); gP = 0; gI = 0; }
    }
    return rows;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function fmt(x, digits) { return x.toFixed(digits).replace(/\.?0+$/, ''); }
  function round(x, digits) { var f = Math.pow(10, digits); return Math.round(x * f) / f; }

  function mode() {
    for (var k = 0; k < KEYS.length; k++) if (document.getElementById(RADIOS[KEYS[k]]).checked) return KEYS[k];
    return 'pmt';
  }

  function fail(msg) {
    var error = document.getElementById('tvError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('tvSchedule').innerHTML = '';
  }

  function update() {
    var solve = mode();
    KEYS.forEach(function (key) {
      var el = document.getElementById(INPUTS[key]);
      el.readOnly = key === solve;
      if (key === solve) el.setAttribute('aria-readonly', 'true'); else el.removeAttribute('aria-readonly');
    });
    document.getElementById('tvAnswerLabel').textContent = NAMES[solve];
    var note = document.getElementById('tvNote');
    note.hidden = true;
    document.getElementById('tvError').hidden = true;

    var n = num('tvN'), iy = num('tvIy'), pv = num('tvPv'), pmt = num('tvPmt'), fv = num('tvFv'),
        py = num('tvPy'), cy = num('tvCy');
    var due = document.getElementById('tvBgn').checked;
    var vals = { n: n, iy: iy, pv: pv, pmt: pmt, fv: fv };
    if (KEYS.some(function (key) { return key !== solve && isNaN(vals[key]); }) || isNaN(py) || isNaN(cy)) return fail('Enter a number in each of the four other keys, P/Y and C/Y (use 0 for an amount that does not apply).');
    if (py < 1 || py > 365 || cy < 1 || cy > 365 || py !== Math.floor(py) || cy !== Math.floor(cy)) return fail('P/Y and C/Y must be whole numbers from 1 to 365.');
    if (solve !== 'n' && (n <= 0 || n > 10000)) return fail('N must be above 0 and at most 10,000 periods.');
    if (solve !== 'iy' && (iy <= -cy * 100 || iy > 10000)) return fail('Enter an I/Y above −' + (cy * 100) + '% and at most 10,000%.');

    var i = solve === 'iy' ? NaN : periodRate(iy / 100, cy, py);
    if (solve === 'fv') fv = solveFv(n, i, pv, pmt, due);
    else if (solve === 'pv') pv = solvePv(n, i, pmt, fv, due);
    else if (solve === 'pmt') pmt = solvePmt(n, i, pv, fv, due);
    else if (solve === 'iy') {
      i = solveRate(n, pv, pmt, fv, due);
      if (isNaN(i)) return fail('No solution for I/Y. Check the signs: PV, PMT and FV need at least one cash outflow (negative) and one inflow (positive).');
      iy = annualRate(i, cy, py) * 100;
    } else {
      n = solveN(i, pv, pmt, fv, due);
      if (!isFinite(n) || n <= 0) return fail('No solution for N. Check the signs (cash out negative, cash in positive) and that PMT is large enough to cover the interest.');
      if (n > 10000) return fail('N works out to more than 10,000 periods.');
    }
    if (![n, iy, pv, pmt, fv, i].every(isFinite) || Math.max(Math.abs(pv), Math.abs(pmt), Math.abs(fv)) > 1e15) return fail('That result is too large to show. Try smaller numbers.');

    // Show the computed value in its key, as a financial calculator does.
    var shown = { n: round(n, 4), iy: round(iy, 6), pv: round(pv, 2), pmt: round(pmt, 2), fv: round(fv, 2) }[solve];
    document.getElementById(INPUTS[solve]).value = String(shown);

    var totalPmt = pmt * n;
    var answer = { n: fmt(n, 4), iy: fmt(iy, 4) + '%', pv: money.format(pv), pmt: money.format(pmt), fv: money.format(fv) }[solve];
    document.getElementById('tvAnswer').textContent = answer;
    document.getElementById('tvTotalPmt').textContent = money.format(totalPmt);
    document.getElementById('tvTotalInt').textContent = money.format(Math.abs(pv + totalPmt + fv));
    document.getElementById('tvNOut').textContent = fmt(n, 4);
    document.getElementById('tvIyOut').textContent = fmt(iy, 4) + '%';
    document.getElementById('tvPvOut').textContent = money.format(pv);
    document.getElementById('tvPmtOut').textContent = money.format(pmt);
    document.getElementById('tvFvOut').textContent = money.format(fv);
    document.getElementById('tvPeriodRate').textContent = fmt(i * 100, 6) + '%';
    document.getElementById('tvEar').textContent = fmt((Math.pow(1 + i, py) - 1) * 100, 4) + '%';
    var years = n / py;
    document.getElementById('tvYears').textContent = fmt(years, 2) + (Math.abs(years - 1) < 1e-9 ? ' year' : ' years');

    if (Math.abs(n - Math.round(n)) > 1e-6) {
      note.hidden = false;
      note.textContent = 'N is not a whole number, so the final payment is a partial one. The schedule shows whole periods only.';
    }
    var group = n > MAX_ROWS ? py : 1;
    document.getElementById('tvPeriodHead').textContent = group === 1 ? 'Period' : 'Year';
    document.getElementById('tvSchedule').innerHTML = schedule(n, i, pv, pmt, due, group).map(function (row) {
      return '<tr><td>' + row.label + (row.part ? ' (part)' : '') + '</td><td>' + money.format(row.pmt) + '</td><td>' +
             money.format(row.int) + '</td><td>' + money.format(row.bal) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tvForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
